def inferir_tipo(apps, schema_editor):
    # Existing categories keep every option they already need: a category used with both signs
    # becomes "ambas", one used only with credits "ingreso"; the rest stay on the "egreso" default.
    alias = schema_editor.connection.alias
    Categoria = apps.get_model("movimientos", "Categoria").objects.using(alias)
    Detalle = apps.get_model("movimientos", "Detalle").objects.using(alias)
    credito = set(Detalle.filter(monto__gt=0).values_list("categoria_id", flat=True).distinct())
    debito = set(Detalle.filter(monto__lt=0).values_list("categoria_id", flat=True).distinct())
    Categoria.filter(pk__in=credito & debito).update(tipo="ambas")
    Categoria.filter(pk__in=credito - debito).update(tipo="ingreso")


